#define PI 3.14159265359

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float time = iTime * 0.35+20.0;
    vec3 color = vec3(0.0);


    float heatBeat = abs(sin(iTime * .2)) * 1.4 + 0.7;
    float scale = 1.0 + heatBeat * .31;

    int NUM_PARTICLES = 15;
    for (int i = 0; i < NUM_PARTICLES; i++) {
        float id = float(i) / float(NUM_PARTICLES);
        float particleTime = (id  * 0.8909090908097069756865754653435);

        float theta = particleTime * 30.14*(sin(time/7.0)) * PI;
        float phi = acos(1.0 - 2.2 * particleTime);

        vec3 spherePos = vec3(
            sin(phi) * cos(theta),
            sin(phi) * sin(theta),
            cos(phi)
        );


        float angle = time * 0.4;
        mat3 rotation = mat3(
            cos(angle), 0.0, -sin(angle),
            0.0,        1.0,  0.0,
            sin(angle), 0.0,  cos(angle)
        );
        spherePos = rotation * spherePos;

        vec2 screenPos = spherePos.xy / (spherePos.z + 2.2) * scale;


        float dist = length(uv - screenPos);
        float viscosity = exp(-dist *2.90) * (0.08 + heatBeat * 1.2)/2.1;


        vec3 particleColor = vec3(
            0.5 + 0.5 * sin(time + id * 16.28),
            0.5 + 0.5 * sin(time + id * 6.28 + PI / 3.0),
            0.5 + 0.5 * sin(time + id * 6.28 + 2.0 * PI / 3.0)
        );

        color += particleColor * viscosity;
    }

float intensity = color.r*color.b*color.g;
 if (intensity < 0.1112) {
fragColor = vec4(.30*exp(intensity*9.));
 } else if (intensity < 1.9112) {
 fragColor = 1.1-vec4(color.rgb*vec3(exp(-intensity*.19030)),1.0);
 } else
    if (intensity < 5.900) {
    fragColor = vec4(color.rgb*vec3(exp(-intensity*0.3030030)),1.0);
    } else {
    fragColor = vec4(2.8-color.rgb*vec3(exp(intensity*.010)),1.0);
    }

}
